Lemma cgl_mid : forall (k : cfgkey) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' dflt w0 errv : word)
    (c spa lo shi ff fp : Z) (LF : list fframe) (m m2 : mem) (pad : list cell) (h32 j216 shb : list byte),
  gv_null k = true -> F = bvmap_empty -> fc = Z_to_bv 32 0 ->
  rw_cells bsegs m2 spa pad -> Z.of_nat (cells_size pad) = bv_unsigned sp + -96 - spa ->
  lo + AGET_VALUE_STACK <= spa -> spa + 96 <= bv_unsigned sp -> spa mod 32 = 0 ->
  rw_cells bsegs m2 (bv_unsigned sp + -96) (cg_frame w0 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs m2 ff [CB 32 h32; CB 216 j216; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs m2 (Z.shiftr ff 3 + 2147450880) [CB 8 cg_shhead; CB 24 shb] ->
  rw_cells bsegs m2 fp [C1 (b8 1)] ->
  stk bsegs m2 lo spa -> mem_inv bsegs m2 ->
  as_RFS H ((2, ff, fp) :: LF) m2 -> fresh_frame H LF 2 ff fp -> ACONST m2 -> stack0 m2 lo shi ->
  munch (cg_W H lo sp ff fp) m m2 -> wmono bsegs m m2 ->
  ro_cells bsegs m2 c [C8 (wz AVP_CONFIG_SVC)] -> ro_cells bsegs m2 (c + O_CFG_HINT) [C4 (wz 4294967295)] ->
  aapp c SZ_CFG -> accessible m2 c SZ_CFG -> c mod 16 = 0 ->
  (c + SZ_CFG <= ff \/ ff + ACG_FSZ <= c) -> (c + SZ_CFG <= fp \/ fp + 1 <= c) ->
  AXStatics2 m2 -> rw_cells bsegs m2 (bv_unsigned tp + -164) [C4 errv] -> tp = Z_to_bv 64 ATP -> acanary m2 ->
  bv_unsigned sp <= 0x7fffffffffff -> bv_unsigned sp <= shi -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (cg_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc
               dflt errv LF lo shi m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) a0' a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) dflt (Z_to_bv 64 (akey_lit k)) (Z_to_bv 64 AL_STR_SCHEDULER) (Z_to_bv 64 c)
             (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s10 s11 t3' t4' t5' t6')
        F (Z_to_bv 64 P_A_CGL_HAND) fc None m2 (seg_rom bsegs)).
